// PayPal's Server SDK (@paypal/paypal-server-sdk, generated by APIMatic) for
// Orders v2 and Payments v2. Mandi's money calls go through it; lib/paypal/rest.ts
// wraps each one with Mandi's idempotency keys, logging and error shape.
//
// Two choices worth knowing:
// - The SDK's HTTP goes through global fetch (a small axios adapter below), so
//   Next.js gets `cache: "no-store"` and tests can stub fetch as before.
// - The bearer token comes from Mandi's own cached token (getAccessToken), so the
//   app, the SDK and the payout calls share one token and one refresh path.
import { ApiError, Client, Environment, OrdersController, PaymentsController, ResponseValidationError } from "@paypal/paypal-server-sdk";

type AxiosLikeConfig = {
  url?: string;
  method?: string;
  headers?: { toJSON?: () => Record<string, unknown> } & Record<string, unknown>;
  data?: unknown;
};

/** axios adapter that sends the SDK's request with global fetch, plus any extra headers. */
const fetchAdapter = (extra: Record<string, string>) => async (config: AxiosLikeConfig) => {
  const raw = typeof config.headers?.toJSON === "function" ? config.headers.toJSON() : (config.headers ?? {});
  const headers: Record<string, string> = {};
  for (const [k, v] of Object.entries(raw)) if (v != null && typeof v !== "function") headers[k] = String(v);
  Object.assign(headers, extra);
  const method = (config.method ?? "get").toUpperCase();
  const res = await fetch(String(config.url), {
    method,
    headers,
    body: method === "GET" || config.data == null ? undefined : String(config.data),
    cache: "no-store",
  });
  const resHeaders: Record<string, string> = {};
  res.headers.forEach((v, k) => (resHeaders[k] = v));
  return { data: await res.text(), status: res.status, statusText: res.statusText, headers: resHeaders, config, request: {} };
};

/**
 * A client carrying the given bearer token. Cheap to build; one per call keeps
 * token refresh simple. `extraHeaders` covers what an SDK method has no
 * parameter for (createOrderTracking takes no PayPal-Request-Id).
 */
export function sdkClient(accessToken: string, extraHeaders: Record<string, string> = {}) {
  return new Client({
    environment: process.env.PAYPAL_ENV === "live" ? Environment.Production : Environment.Sandbox,
    timeout: 30_000,
    clientCredentialsAuthCredentials: {
      oAuthClientId: process.env.PAYPAL_CLIENT_ID ?? "",
      oAuthClientSecret: process.env.PAYPAL_CLIENT_SECRET ?? "",
      // Valid for the life of this client; Mandi's token cache decides when to renew.
      oAuthToken: { accessToken, tokenType: "Bearer", expiry: BigInt(Math.floor(Date.now() / 1000) + 3600) },
    },
    unstable_httpClientOptions: { adapter: fetchAdapter(extraHeaders) },
  });
}

export const controllers = (accessToken: string, extraHeaders?: Record<string, string>) => {
  const client = sdkClient(accessToken, extraHeaders);
  return { orders: new OrdersController(client), payments: new PaymentsController(client) };
};

/** What an SDK call came back with: HTTP status and PayPal's raw JSON body (snake_case, as PayPal sent it). */
export interface SdkOutcome {
  status: number;
  // PayPal bodies are large and loosely shaped; callers read the few fields they need.
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  body: any;
}

const parse = (body: unknown) => {
  if (typeof body !== "string" || !body) return null;
  try {
    return JSON.parse(body);
  } catch {
    return null;
  }
};

/**
 * Runs one SDK call and returns status + raw body, for success and for PayPal
 * errors alike. A response the SDK's (older) schema doesn't recognise still
 * counts: PayPal did the work, so a 2xx is a success whatever the schema says.
 */
export async function runSdk(call: () => Promise<{ statusCode: number; body: unknown }>): Promise<SdkOutcome> {
  try {
    const res = await call();
    return { status: res.statusCode, body: parse(res.body) };
  } catch (err) {
    if (err instanceof ApiError || err instanceof ResponseValidationError) return { status: err.statusCode, body: parse(err.body) };
    throw err;
  }
}
